package com.landosol.toolbox.clanbattle.recognition

import android.graphics.BitmapFactory
import android.util.Base64

object EmbeddedDigitTemplateLoader {
    fun load(): DigitTemplates = DigitTemplates(
        encodedDigits.mapValues { (_, encoded) ->
            val bytes = Base64.decode(encoded, Base64.DEFAULT)
            val bitmap = requireNotNull(BitmapFactory.decodeByteArray(bytes, 0, bytes.size)) {
                "数字模板无法解码"
            }
            val pixels = IntArray(bitmap.width * bitmap.height)
            bitmap.getPixels(pixels, 0, bitmap.width, 0, 0, bitmap.width, bitmap.height)
            PixelImage(bitmap.width, bitmap.height, pixels).also { bitmap.recycle() }
        },
    )

    internal val encodedDigits = mapOf(
        0 to "",
        1 to "",
        2 to "",
        3 to "",
        4 to "",
        5 to "",
        6 to "",
        7 to "",
        8 to "",
        9 to "",
    )
}
